engines = _engines
survival_host = _survival_host
OBJECTIVE = "[Current user objective preserved from compacted history]"
RECALL_HEADER = ("Possibly relevant memories (retrieved from earlier conversations — "
                 "context only, not asserted as fact):")
RECALL = "<relevant-memories>\n" + RECALL_HEADER + "\n- earlier fact\n</relevant-memories>"
STUB = "[Result from earlier conversation — see context summary above]"
SUMMARY = "[Recent Summary (d0, node 999999)]\nEarlier facts.\n[Expand for details: lcm_expand(999999)]"
RECOVERY = "[LCM overflow recovery] Continue from the user's next message."
PROJECTION = ("[LCM survival fit: this assistant message (1000 tokens) is stored verbatim as store id 900000; "
              "lcm_expand / lcm_grep reach the full text. (projection 1200/600)]")


@pytest.fixture(autouse=True)
def isolated_marks(monkeypatch):
    monkeypatch.setattr(ledger, "_PENDING_EMISSIONS", {})
    monkeypatch.setenv("LCM_INGEST_LEDGER", "shadow")
    monkeypatch.setenv("LCM_IDENTITY_ANCHOR", "on")
    monkeypatch.setenv("LCM_HOST_MESSAGE_UID", "off")
    for name in ("_schedule_rollup_maintenance", "_schedule_embedding_maintenance"):
        monkeypatch.setattr(LCMEngine, name, lambda *args: None)


def _looks_generated(role, content, tool_calls=None):
    """Independent stored-byte oracle: no product regex, prefix, codec or predicate."""
    if role == "system":
        return False
    # messages.content is canonical JSON for a protected list/dict payload.
    if isinstance(content, str):
        try:
            parsed = json.loads(content)
        except (ValueError, RecursionError):
            parsed = None
        if isinstance(parsed, (list, dict)):
            content = parsed
    first = content[0] if isinstance(content, list) and content else content
    text = content if isinstance(content, str) else (
        first.get("text", "") if isinstance(first, dict) and first.get("type") == "text" else "")
    text = text if isinstance(text, str) else ""
    leading = text.lstrip()
    summary = re.compile(r"\[(?:Recent|Session Arc|Durable|Depth-\d+) Summary \(d\d+, node \d+\)\]\n")
    if role in ("user", "assistant"):
        match = summary.match(leading)
        if match and "[Expand for details:" in leading[match.end():]:
            return True
        if leading.startswith((OBJECTIVE, "[LCM overflow recovery] ", "<relevant-memories>\n" + RECALL_HEADER)):
            return True
    if role == "tool" and isinstance(content, str) and content.strip() == STUB:
        return True
    if re.search(r"\[LCM survival fit: this [a-z_]+ message \(\d+ tokens\) is stored verbatim as store id \d+; "
                 r"lcm_expand / lcm_grep reach the full text\. \(projection \d+/\d+\)\]", text):
        return True
    if isinstance(tool_calls, str):
        tool_calls = json.loads(tool_calls)
    for call in tool_calls or ():
        function = call.get("function") if isinstance(call, dict) else None
        args = function.get("arguments") if isinstance(function, dict) else None
        try:
            obj = json.loads(args) if isinstance(args, str) else None
        except (ValueError, RecursionError):
            continue
        value = obj.get("lcm_survival_fit") if isinstance(obj, dict) else None
        if isinstance(value, str) and value.startswith("[LCM survival fit: this "):
            return True
    if role == "user" and isinstance(content, str):
        for match in summary.finditer(content):
            if (match.start() >= 2 and content[match.start()-2:match.start()] == "\n\n"
                    and "[Expand for details:" in content[match.end():]):
                return True
        return any("\n\n" + prefix in content for prefix in (OBJECTIVE, "[LCM overflow recovery] "))
    return False


def _rows(conn):
    return conn.execute("SELECT store_id, session_id, role, content, tool_calls FROM messages ORDER BY store_id").fetchall()


def _relations(conn):
    if not conn.execute("SELECT 1 FROM sqlite_master WHERE name='message_relations'").fetchone():
        return Counter()
    return Counter(sid for sid, in conn.execute("SELECT store_id FROM message_relations WHERE kind='generated_unproven'"))


def _assert_visible(conn, scripted=(), *, require_generated=False):
    rows, relations = _rows(conn), _relations(conn)
    generated = [sid for sid, _session, role, content, calls in rows if _looks_generated(role, content, calls)]
    if require_generated:
        assert generated, "the driver must actually store a generated row"
    silent = [(sid, session, role, content[:120]) for sid, session, role, content, calls in rows
              if _looks_generated(role, content, calls) and relations[sid] != 1]
    assert not silent, f"stored generated rows without exactly one relation: {silent}"
    for sid, _session, _role, content, _calls in rows:
        if content in scripted:
            assert relations[sid] == 0, (sid, content[:120])
    return generated


@contextmanager
def _exit_fault(patch, fault):
    """Fault the whole run, including retries; the view fault is emission-only."""
    if fault == "insert":
        def fail(*args, **kwargs):
            raise sqlite3.OperationalError("injected emission insert failure")
        patch.setattr(ledger, "insert_emissions", fail)
    elif fault == "view":
        write = ledger.write_view

        def fail_view(conn, salt, lineage, kind, *args, **kwargs):
            if kind == "emission":
                raise sqlite3.OperationalError("injected emission view failure")
            return write(conn, salt, lineage, kind, *args, **kwargs)

        patch.setattr(ledger, "write_view", fail_view)
    elif fault == "busy":
        write = LCMEngine._compress_exit_write
        blocked = []

        def busy(self, returned, capture):
            if capture is None or not capture[1]:
                return write(self, returned, capture)
            before = self._store._conn.execute("SELECT count(*) FROM ledger_emissions").fetchone()[0]
            prior = count(self, "emission_busy")
            with sqlite3.connect(self._store.db_path) as locker:
                locker.execute("BEGIN IMMEDIATE")
                try:
                    result = write(self, returned, capture)
                finally:
                    locker.rollback()
            assert count(self, "emission_busy") == prior + 1
            assert count(self, "emission_write_failed") == 0
            assert self._store._conn.execute("SELECT count(*) FROM ledger_emissions").fetchone()[0] == before
            if not blocked:
                assert before == 0
            blocked.append(True)
            return result

        patch.setattr(LCMEngine, "_compress_exit_write", busy)
    yield
    if fault == "busy":
        assert blocked, "busy fault must reach a generated exit"


@contextmanager
def _process_restarts(patch):
    """Observe counters before discarding each engine and erase the process registry."""
    shutdown, totals, closed = LCMEngine.shutdown, Counter(), set()

    def stop(self):
        if self not in closed:
            totals.update(getattr(self, "_ingest_ledger_counters", {}))
            closed.add(self)
        try:
            return shutdown(self)
        finally:
            with ledger._PENDING_EMISSIONS_LOCK:
                ledger._PENDING_EMISSIONS.clear()

    patch.setattr(LCMEngine, "shutdown", stop)
    yield totals


def _snapshot(path):
    with sqlite3.connect(path / "lcm.db") as conn:
        return [(session, role, content) for _sid, session, role, content, _calls in _rows(conn)]


# A: published-proof cells; B: the same matrix with a scoped reservation failure.
@pytest.mark.parametrize("fault", ["insert", "view", "busy"])
@pytest.mark.parametrize("in_place", [True, False], ids=["inplace", "rotation"])
@pytest.mark.parametrize("merge,tail", _IN_PLACE_SEAMS)
@pytest.mark.parametrize("restart", ["before", "after"])
def test_failure_then_restart_gate(tmp_path, monkeypatch, fault, in_place, merge, tail, restart):
    scripted = {row["content"] for i in range(1, 28) for row in _turn(i)}
    snapshots = []
    for label, failure in (("control", None), ("fault", fault)):
        root = tmp_path / label
        root.mkdir()
        with monkeypatch.context() as patch, _process_restarts(patch) as totals, _exit_fault(patch, failure):
            result = _run_host_commit_sequence(
                root, patch, in_place=in_place, merge=merge, tail=tail,
                restart_before_first_ingest=1 if restart == "before" else -1,
                restart_after=1 if restart == "after" else -1)
            _assert_clean_commit_sequence(result)
            assert len(result["statuses"]) == _CYCLES
        with sqlite3.connect(root / "lcm.db") as conn:
            _assert_visible(conn, scripted)
            if failure in {"insert", "view"}:
                assert conn.execute("SELECT count(*) FROM ledger_emissions").fetchone()[0] == 0
                assert totals["ledger.emission_write_failed"] >= 1
            elif failure == "busy":
                assert totals["ledger.emission_busy"] >= 1
        snapshots.append(_snapshot(root))
    assert snapshots[0] == snapshots[1]


def _scripted_rows(engine):
    return Counter((role, content) for _sid, _session, role, content, calls in _rows(engine._store._conn)
                   if role != "system" and not _looks_generated(role, content, calls))


def _extended_exit(root, patch, path, measure, caplog, restart):
    """Explicit no-proof exits; stub-first is restarted BEFORE its boundary."""
    if path in {"held", "exception"}:
        engine, result, _rest = _held_fit_after_inplace_boundary(root, measure, patch, path)
        assert engine._compress_commit_proof is None
        assert engine._last_survival_fit is not None
        if path == "exception":
            assert engine.last_compression_status == "error"
            assert engine._survival_fit_reason.startswith("exception:")
        else:
            assert engine.last_compression_noop_reason == "held"
        scripted = _scripted_rows(engine)

        def factory():
            return survival_engine(root)
    else:
        # Same summarizer and driver as #1116's dedicated pre-boundary case.
        calls = [0]

        def summarize(**kwargs):
            calls[0] += 1
            return f"Summary {calls[0]}: " + "lorem ipsum " * 200 + "\nExpand for details about: turns", 1

        patch.setattr(engine_module, "summarize_with_escalation", summarize)
        host = Host(root, TAIL_COUNT["carrier"])
        engine = host.engine
        try:
            committed_session(host, "carrier")
            grow_over_threshold(host)
            scripted = _scripted_rows(engine)
            caplog.set_level(logging.INFO, logger="hermes_lcm")
            durable = engine._durable_commit_proof_payload()
            result, _before = stub_first_result(host, caplog)
            assert engine.last_compression_status == "sanitized"
            # A process-local proof may or may not exist here (the carrier head can leave none); the restart drops
            # it either way. What matters is that nothing became durable before the boundary.
            assert engine._durable_commit_proof_payload() == durable
            # Do not call adopt, rotate, end or on_session_start(compression).
            factory = host._bind
        except BaseException:
            engine.shutdown()
            raise
    try:
        if restart == "after":
            engine.ingest(deepcopy(result))
        engine.shutdown()  # wrapper clears pending registry, matching a real process restart
        engine = factory()
        engine.ingest(deepcopy(result))
        final = _scripted_rows(engine)
        assert not (scripted - final), "every scripted host row remains stored"
        _assert_visible(engine._store._conn, {text for _role, text in scripted}, require_generated=True)
    finally:
        engine.shutdown()


@pytest.mark.parametrize("path", ["held", "exception", "stub-before-boundary"])
@pytest.mark.parametrize("fault", ["insert", "view", "busy"])
@pytest.mark.parametrize("restart", ["before", "after"])
def test_no_proof_exit_restart_gate(tmp_path, monkeypatch, survival_host, caplog, path, fault, restart):
    snapshots = []
    for label, failure in (("control", None), ("fault", fault)):
        root = tmp_path / label
        root.mkdir()
        with monkeypatch.context() as patch, _process_restarts(patch) as totals, _exit_fault(patch, failure):
            _extended_exit(root, patch, path, survival_host, caplog, restart)
        with sqlite3.connect(root / "lcm.db") as conn:
            if failure in {"insert", "view"}:
                assert conn.execute("SELECT count(*) FROM ledger_emissions").fetchone()[0] == 0
                assert totals["ledger.emission_write_failed"] >= 1
            elif failure == "busy":
                assert totals["ledger.emission_busy"] >= 1
        snapshots.append(_snapshot(root))
    assert snapshots[0] == snapshots[1]


# C: real emitter helpers, then a proofless empty child. No classification patches.
def _call(arguments, name="real"):
    return {"id": name, "type": "function", "function": {"name": "terminal", "arguments": arguments}}


def _projection_calls(engine):
    def mark(sid):
        return engine._survival_projected_fields(
            {"role": "assistant", "store_id": sid, "content": "raw"}, 1000, 1200, 100, legacy=True)["content"]

    quoted = _call(json.dumps({"lcm_survival_fit": "quoted " + (mark(900000) + "\n") * 4}), "quoted")
    decoys = [engine._survival_bounded_call(_call("x" * 6000, f"decoy-{i}"), mark(900001 + i)) for i in range(4)]
    return [quoted, *decoys, _call("x" * 6000)]


def _render_recovery(engine, tail):
    # Render in an empty session, as the recovery fallback does when no DAG
    # summaries exist. The target store's parent already has summary nodes.
    config = LCMConfig(database_path=str(engine._store.db_path.parent / "recovery-source.db"), fresh_tail_count=10)
    emitter = LCMEngine(config=config, hermes_home=str(engine._store.db_path.parent / "recovery-home"))
    try:
        emitter.on_session_start("recovery-source", platform="acp", context_length=200_000)
        return emitter._assemble_overflow_recovery_context(None, tail, assembly_cap_override=120)
    finally:
        emitter.shutdown()


def _forced_output(engine, variant, compressed):
    text = next(row["content"] for row in compressed if isinstance(row.get("content"), str)
                and "Summary (d" in row["content"])
    start = engine._LCM_SUMMARY_PART_HEADER_RE.search(text).start()
    text = text[start:]
    end = engine._verified_lcm_summary_prefix_end(text)
    assert end is not None
    summary = {"role": "user", "content": text[:end]}
    if variant == "summary":
        return [summary]
    if variant == "carrier":
        return _host_merge_consecutive_users([summary, {"role": "user", "content": "carrier host text"}])
    if variant == "large-carrier":
        # Over the whole-row floor (100k chars at a 200k window): the stored payload is an externalized stub.
        return _host_merge_consecutive_users([summary, {"role": "user", "content": "large host text " * 7_000}])
    if variant == "objective-first":
        return [{"role": "user", "content": OBJECTIVE + "\ncurrent ask\n\n" + summary["content"]}]
    if variant in {"recall", "structured-list", "structured-dict"}:
        recall = engine._wrap_relevant_memories(RECALL_HEADER, ["- earlier fact"])
        content = ([{"type": "text", "text": "structured host text"}] if variant == "structured-list"
                   else {"type": "text", "text": "structured host text"})
        target = {"role": "user", "content": "recall host text" if variant == "recall" else content}
        return [engine._prepend_generated_context_to_message(target, recall)]
    if variant == "recovery":
        output = _render_recovery(engine, [{"role": "tool", "tool_call_id": "orphan", "content": "orphan result"}])
        assert len(output) == 1 and output[0]["content"].startswith("[LCM overflow recovery] ")
        return output
    if variant == "stub":
        return [{"role": "assistant", "content": "", "tool_calls": [_call("{}", "missing")]},
                engine._missing_tool_result_stub("missing")]
    if variant == "joined-summary":
        return _host_merge_consecutive_users([{"role": "user", "content": "older host text"}, summary])
    if variant == "successful-descriptor":
        output = [summary]
        engine._compress_exit_write(output, (output, [dict(kind="summary", output_occurrence=dict(index=0, of=1))], None))
        digest = ledger.identity_digest(engine._store.ingest_ledger_salt(), summary)
        assert any(row["descriptor_digest"] == digest for row in sql_rows(engine, "ledger_emissions"))
        return output
    if variant == "tool-call-projection":
        source = {"role": "assistant", "content": "", "tool_calls": _projection_calls(engine), "timestamp": 9.0}
        before = engine._store.max_store_id()
        engine.ingest([source])
        sid = engine._store.max_store_id()
        assert sid > before and engine._store.get(sid)["content"] == ""
        projected = {**source, **engine._survival_projected_fields(engine._store.get(sid), 1000, 1200, 100)}
        assert projected["content"] == "" and projected["tool_calls"] != source["tool_calls"]
        assert _looks_generated("assistant", "", projected["tool_calls"])
        return [projected]
    if variant == "joined-recovery":
        from tests.test_issue_529_overflow_followups import ORPHAN, OVERSIZED
        older = {"role": "user", "content": "OLDER_ASK: summarize the report."}
        newest = {"role": "user", "content": "NEWEST_ASK: rebuild the index " * 300}
        tail = [older, {"role": "assistant", "content": OVERSIZED}, newest, ORPHAN]
        engine.ingest(tail)  # all host rows remain durable even if the recovery omits the newest
        output = _render_recovery(engine, tail)
        assert len(output) == 2 and output[0] == older
        assert output[1]["content"].startswith("[LCM overflow recovery] ")
        return _host_merge_consecutive_users(output)
    raise AssertionError(variant)


_HOST_TEXT = {"carrier": "carrier host text", "joined-summary": "older host text", "recall": "recall host text",
              "structured-list": "structured host text", "structured-dict": "structured host text"}


@pytest.mark.parametrize("variant", ["summary", "carrier", "large-carrier", "objective-first", "recall", "recovery",
                                     "stub", "joined-summary", "successful-descriptor", "structured-list",
                                     "structured-dict", "tool-call-projection", "joined-recovery"])
def test_forced_restore_in_empty_child(tmp_path, monkeypatch, variant):
    engine, pre, compressed = _compacted_engine(tmp_path, monkeypatch)
    try:
        output = _forced_output(engine, variant, compressed)
        scripted = _scripted_rows(engine)
        engine.on_session_end("S0", pre)
        engine.on_session_start("S1", boundary_reason="compression", old_session_id="S0", platform="acp")
        # A rotation normally carries DAG nodes. Keep this one in its parent, so
        # byte-identical successful emissions cannot be skipped as child scaffolds.
        for node in engine._dag.get_session_nodes("S1"):
            engine._store._conn.execute("UPDATE summary_nodes SET session_id='S0' WHERE node_id=?", (node.node_id,))
        engine._store.write_metadata_json(["compaction_commit_proof:S1"], "null")
        engine._store._conn.commit()
    finally:
        engine.shutdown()
    with ledger._PENDING_EMISSIONS_LOCK:
        ledger._PENDING_EMISSIONS.clear()
    cold = LCMEngine(config=_config(tmp_path), hermes_home=str(tmp_path / "home"))
    try:
        cold.on_session_start("S1", platform="acp", context_length=200_000)
        assert cold._store.get_session_count("S1") == 0
        assert cold._durable_commit_proof_payload() is None
        cold.ingest([*deepcopy(output), _turn(13)[1]])
        conn = cold._store._conn
        assert not (scripted - _scripted_rows(cold)), "0 loss of scripted host rows"
        assert _turn(13)[1]["content"] in {row[3] for row in _rows(conn)}
        child = [row for row in _rows(conn) if row[1] == "S1"]
        if variant in _HOST_TEXT:
            assert any(_HOST_TEXT[variant] in (row[3] or "") for row in child), "the host text is stored in S1"
        if variant == "large-carrier":
            # The stored bytes no longer show the summary, so the oracle cannot see it: check the stub directly.
            relations = _relations(conn)
            stubs = [row[0] for row in child if (row[3] or "").startswith("[Externalized payload")]
            assert stubs and all(relations[sid] == 1 for sid in stubs), (stubs, relations)
            _assert_visible(conn, {text for _role, text in scripted})
        else:
            generated = _assert_visible(conn, {text for _role, text in scripted}, require_generated=True)
            assert {row[0] for row in child}.intersection(generated), "the forced child re-store must not pass vacuously"
    finally:
        cold.shutdown()


# D/H: precedence, roles, exclusions and malformed/structured inputs.
_MARKERS = [
    (SUMMARY, "summary"), (OBJECTIVE + "\nask", "scaffold"), (RECOVERY, "recovery"),
    (RECALL, "recall"), (STUB, "stub"), ("head\n" + PROJECTION + "\ntail", "projection"),
    ("plain\n\n" + SUMMARY, "summary_joined"),
    ("plain\n\n" + OBJECTIVE, "scaffold_joined"),
    ("plain\n\n" + RECOVERY, "recovery_joined"),
]
_EXCLUDED = [
    "plain " + SUMMARY, "plain\n" + SUMMARY, SUMMARY.split("[Expand for details:")[0],
    "[LCM active replay placeholder: hidden]", "[LCM persisted-output: hidden]",
    "[LCM sensitive redaction: hidden]", "[Externalized tool output: file]", "[Externalized payload: file]",
    "[Your active task list was preserved across context compression]\n- todo",
    "CONTEXT COMPACTION/SUMMARY", "<relevant-memories>\nOther plugin's memory\n</relevant-memories>",
    STUB + " more", "plain\n\n" + RECALL, "plain " + OBJECTIVE, "plain " + RECOVERY,
    "<pre-answer-evidence>evidence</pre-answer-evidence>",
]


def _role_kind(role, kind):
    if kind == "projection":
        return kind if role != "system" else None
    if kind == "stub":
        return kind if role == "tool" else None
    if kind.endswith("_joined"):
        return kind if role == "user" else None
    return kind if role in {"user", "assistant"} else None


@pytest.mark.parametrize("role", ["user", "assistant", "tool", "system", "unknown"])
@pytest.mark.parametrize("content,kind", _MARKERS)
def test_predicate_role_table(role, content, kind):
    expected = _role_kind(role, kind)
    assert LCMEngine._lcm_generated_marker({"role": role, "content": content}) == expected
    assert _looks_generated(role, content) == (expected is not None)


@pytest.mark.parametrize("role", ["user", "assistant", "tool", "system"])
@pytest.mark.parametrize("content", _EXCLUDED)
def test_predicate_exclusions(role, content):
    assert LCMEngine._lcm_generated_marker({"role": role, "content": content}) is None
    assert not _looks_generated(role, content)


@pytest.mark.parametrize("content,expected", [
    (" \t\n" + SUMMARY, "summary"), (" \t" + STUB + " \n", None),
    ([{"type": "text", "text": RECALL}, {"type": "image_url"}], "recall"),
    ({"type": "text", "text": SUMMARY}, "summary"),
    ([{"type": "image_url"}, {"type": "text", "text": SUMMARY}], None),
    ([{"type": "text", "text": "plain\n\n" + SUMMARY}], None),
    ([{"type": "text", "text": PROJECTION}], "projection"),
    ([], None), ({}, None), (None, None), (42, None),
    ([{"type": "text", "text": 42}], None),
    (SUMMARY + "\n\n" + OBJECTIVE + "\n" + PROJECTION, "summary"),
    (OBJECTIVE + "\n\n" + SUMMARY, "scaffold"),
    ("plain\n\n" + RECOVERY + "\n\n" + SUMMARY, "summary_joined"),
])
def test_predicate_edges(content, expected):
    assert LCMEngine._lcm_generated_marker({"role": "user", "content": content}) == expected
    assert _looks_generated("user", content) == (expected is not None)


@pytest.mark.parametrize("role", ["user", "assistant", "tool", "system", "unknown"])
@pytest.mark.parametrize("arguments,marked", [
    (json.dumps({"lcm_survival_fit": PROJECTION + " Its tool-call arguments are not in live context."}), True),
    (json.dumps({"lcm_survival_fit": "[LCM survival fit: this short notice"}), True),
    (json.dumps({"lcm_survival_fit": "quoted " + PROJECTION}), False),
    (json.dumps({"lcm_survival_fit": 1}), False), ("[]", False), ("{invalid", False), (None, False),
])
def test_predicate_bounded_call_only(role, arguments, marked):
    calls = [_call(arguments)]
    expected = "projection" if marked and role != "system" else None
    assert LCMEngine._lcm_generated_marker({"role": role, "content": "", "tool_calls": calls}) == expected
    assert _looks_generated(role, "", calls) == (expected is not None)


@pytest.mark.parametrize("calls", [None, "invalid", {}, [None, {"function": None}, {"function": []}]])
def test_predicate_malformed_calls(calls):
    assert LCMEngine._lcm_generated_marker({"role": "assistant", "content": "", "tool_calls": calls}) is None


@pytest.mark.parametrize("role,content,expected", [
    ("user", OBJECTIVE + "\nactual user quote", "scaffold"),
    ("user", "plain " + SUMMARY, None), ("user", "plain\n\n" + SUMMARY, "summary_joined"),
    ("assistant", "plain\n\n" + SUMMARY, None), ("tool", SUMMARY, None),
    ("tool", STUB, "stub"), ("tool", STUB + " more", None),
    *[("user", content, None) for content in _EXCLUDED],
])
def test_stored_marker_edges(engines, role, content, expected):
    engine = engines()
    row = {"role": role, "content": content, "timestamp": 10.0}
    rows = ([{"role": "assistant", "content": "", "tool_calls": [_call("{}", "edge")], "timestamp": 9.0},
             {**row, "tool_call_id": "edge"}] if role == "tool" else [row])
    engine.ingest(rows)
    stored = [r for r in engine._store.get_session_messages("S") if r["content"] == content]
    assert len(stored) == 1, "marker quotes are stored, never dropped"
    relations = _relations(engine._store._conn)
    assert relations[stored[0]["store_id"]] == int(expected is not None)
    assert count(engine, "marker_rows." + str(expected)) == int(expected is not None)


@pytest.mark.parametrize("suffix,expected", [(RECALL, "recall"), ("ordinary remainder", None)])
def test_r3_uses_stored_remainder_bytes(engines, suffix, expected):
    engine = engines()
    head = [{"role": "user", "content": "first", "timestamp": 1.0},
            {"role": "assistant", "content": "first reply", "timestamp": 2.0}]
    donor = {"role": "user", "content": "held donor\n\n indented", "timestamp": 10.0}
    engine.ingest([*head, donor])
    composite = {**donor, "content": donor["content"] + "\n\n" + suffix}
    engine.ingest([*head, composite, {"role": "assistant", "content": "reply", "timestamp": 11.0}])
    row = next(r for r in engine._store.get_session_messages("S") if r["content"] == suffix)
    binding = next(b for b in sql_rows(engine, "occurrence_bindings") if b["store_id"] == row["store_id"])
    assert binding["disposition"] == "composite_part"
    assert _relations(engine._store._conn)[row["store_id"]] == int(expected is not None)
    assert count(engine, "marker_rows." + str(expected)) == int(expected is not None)


# F: the relation precedes ordinal planning, while all counters wait for commit.
def test_crossed_bounds_keep_marker_relations_and_counters(engines, monkeypatch):
    engine = engines()
    left = {"role": "user", "content": "left", "timestamp": 10.0}
    right = {"role": "assistant", "content": "right", "timestamp": 20.0}
    engine.ingest([left, right])
    stored = engine._store.get_session_messages("S")
    prematch, before = engine._identity_anchor_prematch, ledger_state(engine)

    def crossed(*args, **kwargs):
        plan = prematch(*args, **kwargs)
        plan.update(cursor=0, matched={0: [stored[1]], 2: [stored[0]]}, replayed={0, 2})
        return plan

    monkeypatch.setattr(engine, "_identity_anchor_prematch", crossed)
    engine.ingest([right, {"role": "user", "content": RECALL, "timestamp": 15.0}, left])
    assert count(engine, "skipped_crossed") == 1
    assert ledger_state(engine) == before  # no ordinals, bindings, observations or vector
    assert count(engine, "generated_unproven_rows") == count(engine, "marker_rows.recall") == 1
    assert len(_assert_visible(engine._store._conn, {"left", "right"}, require_generated=True)) == 1


def test_pending_and_marker_union_is_one_relation(engines, monkeypatch):
    from tests.test_issue_2055_pending_emissions import fail_exit
    engine = engines()
    rows = [{"role": "user", "content": RECALL}]
    fail_exit(engine, monkeypatch, rows=rows)
    with monkeypatch.context() as patch, _exit_fault(patch, "insert"):
        calls, add = [], engine._store.add_message_relations

        def record(groups):
            calls.append(deepcopy(groups))
            return add(groups)

        patch.setattr(engine._store, "add_message_relations", record)
        engine.ingest(rows)
    groups = [g for call in calls for g in call if any(row[1] == "generated_unproven" for row in g)]
    assert len(groups) == len(groups[0]) == 1
    assert count(engine, "generated_unproven_rows") == count(engine, "marker_rows.recall") == 1
    _assert_visible(engine._store._conn, require_generated=True)


@pytest.mark.parametrize("failure", ["write", "off", "not-ready", "read-only"])
def test_accepted_ledger_gaps_do_not_publish_marker_counters(engines, monkeypatch, failure):
    engine = engines()
    if failure == "off":
        monkeypatch.setenv("LCM_INGEST_LEDGER", "off")
    elif failure == "write":
        def fail(*args, **kwargs):
            raise sqlite3.OperationalError("injected ingest view failure")
        monkeypatch.setattr(ledger, "write_view", fail)
    elif failure == "not-ready":
        monkeypatch.setattr(engine._store, "ingest_ledger_state", lambda: "absent")
    else:
        # Exercise the writer's sentinel without changing the classification path.
        write = engine._write_ingest_ledger

        def read_only(*args, **kwargs):
            engine._ingest_read_only = "test sentinel"
            try:
                return write(*args, **kwargs)
            finally:
                del engine._ingest_read_only
        monkeypatch.setattr(engine, "_write_ingest_ledger", read_only)
    engine.ingest([{"role": "user", "content": RECALL}])
    assert any(r["content"] == RECALL for r in engine._store.get_session_messages("S"))
    assert not _relations(engine._store._conn)
    assert count(engine, "generated_unproven_rows") == count(engine, "marker_rows.recall") == 0
    assert count(engine, "write_failed") == int(failure == "write")


# E: frozen caad1f5f8 writer; copied mechanically, not a second implementation oracle.
# Keeping this local makes the SQL assertion runnable without git or a base checkout.
def _main_ledger_write(self, attempt, after_commit, attribution):
    store, conn = self._store, self._store._conn
    try:
        if store.ingest_ledger_state() != "ready" or getattr(self, "_ingest_read_only", None) is not None:
            return
        if store.ingest_ledger_salt() != attempt["salt"]:
            self._ledger_count("ledger.salt_changed")
            return
    except Exception as exc:
        self._raise_ingest_busy(exc)
        self._ledger_count("ledger.prepare_failed", exc)
        return
    started, delta = engine_module._perf_counter(), Counter()
    pending_relation_schema = getattr(store, "_pending_relation_schema", False)
    try:
        with engine_module._sqlite_savepoint(conn, abort_on_cleanup_failure=True, owner_active=True, foreground_ingest=True):
            key = "session_lineage:" + str(self._session_id)
            persisted = conn.execute("SELECT value FROM ledger_meta WHERE key=?", (key,)).fetchone()
            lineage = persisted[0] if persisted else attempt["lineage"]
            if persisted and attempt["resolved"] is not None and lineage != attempt["resolved"]:
                delta["ledger.lineage_drift"] += 1
            ids = set(attempt["matched"].values()) | {sid for sid, _kind, _stamp in attempt["observations"]}
            by_store = {}
            for sid, occ, ordinal in conn.execute(
                "SELECT store_id,occ_id,ordinal FROM occurrence_bindings WHERE lineage=? "
                "AND store_id IN (SELECT value FROM json_each(?))", (lineage, json.dumps(sorted(ids)))):
                by_store.setdefault(sid, []).append((occ, ordinal))
            bound = {idx: by_store[sid][0] for idx, sid in attempt["matched"].items()
                     if len(by_store.get(sid, ())) == 1}
            pending = sorted(attempt["stored"])
            placements = [ledger.Placement(
                next((bound[j][1] for j in sorted(bound, reverse=True) if j < idx), None),
                next((bound[j][1] for j in sorted(bound) if j > idx), None)) for idx in pending]
            ordinals, respace = [], {}
            if pending:
                if any(p.right is not None for p in placements):
                    existing = ledger.lineage_ordinals(conn, lineage)
                else:
                    maximum = conn.execute("SELECT max(ordinal) FROM occurrence_bindings WHERE lineage=?", (lineage,)).fetchone()[0]
                    existing = sorted({v for v in [maximum, *(p.left for p in placements)] if v is not None})
                try:
                    ordinals, respace = ledger.plan_ordinals(existing, placements)
                except ledger.LedgerError as exc:
                    if str(exc) != "placement bounds must be non-decreasing in view order":
                        raise
                    self._ledger_count("ledger.skipped_crossed")
                    return
            entries = [entry._replace(ref=bound[idx][0] if idx in bound else None)
                       for idx, entry in enumerate(attempt["entries"])]
            previous = ledger.newest_view(conn, lineage, "ingest")
            same = previous is not None and previous["prefix_chain"] == attempt["chain"]
            old = ledger.decode_entries(previous["entries"]) if same else []
            changed_ref = same and any(e.ref is not None and e.ref != prior.ref for e, prior in zip(entries, old))
            observations, seen = [], {}
            for occ, kind, stamp in conn.execute(
                "SELECT occ_id,kind,stamp FROM stamp_observations WHERE lineage=? "
                "AND occ_id IN (SELECT value FROM json_each(?))",
                (lineage, json.dumps([item[0] for values in by_store.values() for item in values]))):
                seen.setdefault((occ, kind), set()).add(stamp)
            for sid, kind, stamp in attempt["observations"]:
                if sid not in attempt["stored"].values() and len(by_store.get(sid, ())) != 1:
                    continue
                occ, stamp = by_store[sid][0][0] if sid in by_store else None, ledger.stamp_text(stamp)
                stamps = seen.setdefault((occ if occ is not None else ("new", sid), kind), set())
                if stamp not in stamps and len(stamps) < 4:
                    observations.append((sid, kind, stamp))
                    stamps.add(stamp)
            if not persisted and attempt["resolved"] is not None:
                conn.execute("INSERT INTO ledger_meta(key,value) VALUES (?,?)", (key, lineage))
            if pending or observations or not same or changed_ref:
                seq = ledger.next_view_seq(conn)
                if respace:
                    ledger.apply_respace(conn, lineage, respace)
                    delta["ledger.respaced"] += 1
                rows = [dict(ordinal=ordinal, store_id=attempt["stored"][idx],
                    identity_digest=attempt["remainders"].get(idx, attempt["entries"][idx].identity_digest),
                    stamp=None if idx in attempt["remainders"] else attempt["stamps"][idx],
                    disposition="composite_part" if idx in attempt["remainders"] else "stored", key_rank=None, view_seq=seq)
                    for idx, ordinal in zip(pending, ordinals)]
                for idx, occ in zip(pending, ledger.insert_bindings(conn, lineage, rows)):
                    by_store[attempt["stored"][idx]] = [(occ, None)]
                    entries[idx] = entries[idx]._replace(ref=None if idx in attempt["remainders"] else occ)
                for sid, kind, stamp in observations:
                    ledger.add_stamp_observation(conn, lineage, by_store[sid][0][0], stamp, kind, seq)
                ledger.write_view(conn, attempt["salt"], lineage, "ingest", None, entries,
                                         view_seq=seq, precomputed_chain=attempt["chain"])
                delta.update({"ledger.bindings_written": len(rows), "ledger.views_written": 1})
            if ledger.has_pending(store.db_identity):
                digests = ledger.pending_emission_digests((store.db_identity, attempt["salt"]),
                                                               lineage, attempt.get("retried_emissions", ()))
                groups = [[(sid, "generated_unproven", None, None, None)] for idx, sid in attempt["stored"].items()
                          if attempt["entries"][idx].identity_digest in digests]
                if groups:
                    delta["ledger.generated_unproven_rows"] += store.add_message_relations(groups)
        for key, count in delta.items():
            after_commit.append(lambda key=key, count=count: self._ledger_count(key, amount=count))
    except BaseException as exc:
        store._pending_relation_schema = pending_relation_schema
        if (not isinstance(exc, Exception) or engine_module._is_ingest_busy_error(exc)
                or isinstance(exc, engine_module._SqliteSavepointError) or not conn.in_transaction):
            raise
        self._ledger_count("ledger.write_failed", exc)
    finally:
        attribution["ledger_ms"] += (engine_module._perf_counter() - started) * 1000



def test_plain_ingest_has_exact_main_sql(engines, monkeypatch):
    engine = engines()
    write, comparisons = engine._write_ingest_ledger, []

    def compare(attempt, callbacks, attribution):
        assert not attempt.get("stored_markers") and not ledger.has_pending(engine._store.db_identity)
        conn, baseline, candidate = engine._store._conn, [], []
        # Both writers see the identical state inside the real foreground owner.
        # The baseline's isolated effects and callbacks are discarded.
        conn.execute("SAVEPOINT compare_main")
        try:
            conn.set_trace_callback(baseline.append)
            _main_ledger_write(engine, deepcopy(attempt), [], Counter())
        finally:
            conn.set_trace_callback(None)
            conn.execute("ROLLBACK TO SAVEPOINT compare_main")
            conn.execute("RELEASE SAVEPOINT compare_main")
        conn.set_trace_callback(candidate.append)
        try:
            write(attempt, callbacks, attribution)
        finally:
            conn.set_trace_callback(None)
        assert candidate == baseline
        comparisons.append(candidate)

    monkeypatch.setattr(engine, "_write_ingest_ledger", compare)
    rows = [{"role": "user", "content": "ordinary question", "timestamp": 10.0},
            {"role": "assistant", "content": "ordinary answer", "timestamp": 11.0}]
    engine.ingest(deepcopy(rows))
    engine.ingest(deepcopy(rows))
    assert len(comparisons) == 2 and all(comparisons)
    assert count(engine, "views_written") == 1


@pytest.mark.parametrize("pending_whole", [True, False])
def test_pending_composite_still_matches_full_entry_digest(engines, monkeypatch, pending_whole):
    from tests.test_issue_2055_pending_emissions import fail_exit
    engine = engines()
    head = [{"role": "user", "content": "head", "timestamp": 1.0},
            {"role": "assistant", "content": "reply", "timestamp": 2.0}]
    donor = {"role": "user", "content": "held donor", "timestamp": 10.0}
    engine.ingest([*head, donor])
    suffix = "ordinary suffix"
    whole = {**donor, "content": donor["content"] + "\n\n" + suffix}
    # No marker: this isolates P1c-2a's full-entry pending semantics after the move.
    fail_exit(engine, monkeypatch, rows=[whole if pending_whole else {**whole, "content": suffix, "timestamp": None}])
    with monkeypatch.context() as patch, _exit_fault(patch, "insert"):
        engine.ingest([*head, whole, {"role": "assistant", "content": "new reply", "timestamp": 11.0}])
    row = next(r for r in engine._store.get_session_messages("S") if r["content"] == suffix)
    assert _relations(engine._store._conn)[row["store_id"]] == int(pending_whole)
    assert count(engine, "generated_unproven_rows") == int(pending_whole)
